using LiAIChat.Archive; using LiAIChat.State; using RimWorld; using System.Linq; using Verse; using Verse.AI;
namespace LiAIChat.Commentary { public static class CommentaryIdleWritingManager {
public static void TryAssignIdleWriters(){if(!CommentaryResearch.IsFinished)return;foreach(var m in Find.Maps.Where(x=>x.IsPlayerHome))foreach(var p in m.mapPawns.FreeColonistsSpawned){if(p.CurJob==null||p.CurJob.def!=JobDefOf.Wait)continue;var d=m.listerThings.AllThings.FirstOrDefault(x=>x.def.defName=="LiAIChat_WritingDesk");var s=m.listerThings.AllThings.FirstOrDefault(CommentaryService.IsShelf);var st=PawnAIStateManager.GetState(p);var t=DefDatabase<EarthTextDef>.AllDefsListForReading.FirstOrDefault(x=>st.GetEarthTextFamiliarity(x.defName)>=.4f&&ColonyLibrary.HasText(x));if(!CanWrite(p,d,s,t)||!ConsumePaper(m))continue;var w=CommentaryService.Works.FirstOrDefault(x=>x.AuthorPawnId==p.thingIDNumber&&string.IsNullOrWhiteSpace(x.Body))??CommentaryService.CreateDraft(p,t,s);var b=w==null?null:CommentaryService.FindManuscript(w.BookThingId);if(b!=null)p.jobs.TryTakeOrderedJob(new Job(LiAIChatJobDefOf.LiAIChat_WriteEarthCommentary,d,b),JobTag.Misc);}}
public static bool CanWrite(Pawn p,Thing d,Thing s,EarthTextDef t){if(p==null||p.Drafted||d==null||s==null||t==null||p.needs?.mood==null||p.needs.mood.CurLevelPercentage<.65f)return false;var room=d.GetRoom();if(room==null||room.PsychologicallyOutdoors)return false;if(!d.Map.thingGrid.ThingsListAt(d.Position).Any(x=>x.def.building!=null&&x.def.building.isSittable))return false;return d.Map.listerThings.AllThings.Any(x=>x.def.defName=="LiAIChat_SteelPen"||x.def.defName=="LiAIChat_SilverPen"||x.def.defName=="LiAIChat_GoldPen");}
static bool ConsumePaper(Map m){var x=m.listerThings.AllThings.FirstOrDefault(t=>t.def.defName=="LiAIChat_WritingPaper"&&t.stackCount>=5);if(x==null)return false;x.SplitOff(5).Destroy();return true;} public static void AddWritingTick(Thing_EarthCommentaryManuscript b){var w=b==null?null:CommentaryService.Get(b.thingIDNumber);if(w!=null&&string.IsNullOrWhiteSpace(w.Body))w.WritingProgress=System.Math.Min(1f,w.WritingProgress+1f/240000f);}}}
